mapper.select:
select #{workTime,jdbcType=VARCHAR} as workTime,
from staff_pay_personnel_slip where delete_flag = 0 and staff_pay_slip_id = #{staffPaySlipId,jdbcType=BIGINT}
and (back_state = 1 or show_state = 0)
and id is not null
and social_security_company_id = #{socialSecurityCompanyId,jdbcType=BIGINT}
and company_id = #{companyId,jdbcType=BIGINT}
and organ_id = #{organId,jdbcType=BIGINT}
and department_id = #{departmentId,jdbcType=BIGINT}
and job_post_id = #{jobPostId,jdbcType=BIGINT}
and team_id = #{teamId,jdbcType=BIGINT}
and job_no like concat('%',#{jobNo,jdbcType=VARCHAR},'%')
and real_name like concat('%',#{realName,jdbcType=VARCHAR},'%')
and organ_manager_user_id = #{organManagerUserId,jdbcType=BIGINT}
and superior_manager_user_id = #{superiorManagerUserId,jdbcType=BIGINT}
and (organ_manager_user_id = #{organManagerUserId,jdbcType=BIGINT} or superior_manager_user_id = #{superiorManagerUserId,jdbcType=BIGINT})
and DATE_FORMAT(entry_time,'%Y-%m-%d') >= DATE_FORMAT(#{entryTime,jdbcType=DATE},'%Y-%m-%d')
and DATE_FORMAT(entry_time,'%Y-%m-%d') <= DATE_FORMAT(#{entryTimeEnd,jdbcType=DATE},'%Y-%m-%d')
and find_in_set(company_id,#{companyIds,jdbcType=VARCHAR})
and find_in_set(organ_id,#{organIds,jdbcType=VARCHAR})
and find_in_set(department_id,#{departmentIds,jdbcType=VARCHAR})
and find_in_set(job_post_id,#{jobPostIds,jdbcType=VARCHAR})
and find_in_set(team_id,#{teamIds,jdbcType=VARCHAR})
and find_in_set(social_security_company_id,#{socialSecurityCompanyIds,jdbcType=VARCHAR})
and find_in_set(organ_id,#{authData,jdbcType=VARCHAR})
order by
company_id desc, social_security_company_id desc,
organ_opinion desc, superior_opinion desc, boss_opinion desc,
organ_id asc

mapper.update:
update staff_pay_personnel_slip set
delete_flag = 1
where staff_pay_slip_id = #{staffPaySlipId,jdbcType=BIGINT}

update staff_pay_personnel_slip set
show_state = #{showState,jdbcType=INTEGER},back_state = #{backState,jdbcType=INTEGER}
where staff_pay_slip_id = #{staffPaySlipId,jdbcType=BIGINT}

    and back_state = #{oldBackState,jdbcType=INTEGER}


    and show_state = #{oldShowState,jdbcType=INTEGER}

;

update staff_pay_personnel_slip set
organ_opinion = null,superior_opinion = null,boss_opinion = null
where staff_pay_slip_id = #{staffPaySlipId,jdbcType=BIGINT};
